//! Runtime types for file services generated by `ras-file-macro`.
//!
//! The `file_service!` macro generates a handler trait whose methods take and
//! return the types in this crate. Implementations of that trait use them
//! directly; the generated Axum server adapts HTTP requests into them.
//!
//! - [`FileRequestContext`] carries the request method, path, headers and the
//!   authenticated user, if any.
//! - [`IncomingFile`] is a streaming upload part with a byte limit. Read it
//!   with [`IncomingFile::next_chunk`] or skip it with [`IncomingFile::drain`];
//!   the generated server rejects an upload whose file part was not read to
//!   the end.
//! - [`UploadSummary`] lists the accepted parts when an upload finishes.
//! - [`JsonResponse`] is the upload response body with its status and headers.
//! - [`DownloadResponse`] builds a download from bytes or a stream.
//! - [`FileError`] and [`FileResult`] are the error type and its result alias.
//!   [`FileError::status`] and [`FileError::client_message`] give the HTTP
//!   status and the message the client sees.
//! - [`sanitize_filename`] reduces an untrusted filename to one safe path
//!   component.
//!
//! The crate has no Cargo features. See the
//! [`file_service!` guide](https://github.com/JedimEmO/rust-api-stack/blob/master/documentation/src/macros/file-service.md)
//! for how the handler methods use these types.

#![warn(missing_docs)]

use std::{pin::Pin, time::SystemTime};

use bytes::Bytes;
use futures_core::Stream;
use futures_util::StreamExt;
use http::{HeaderMap, HeaderValue, StatusCode, header};
use ras_auth_core::AuthenticatedUser;
use thiserror::Error;

pub use bytes;
pub use futures_core;
pub use futures_util;
pub use http;
pub use ras_auth_core::sanitize_log_detail;
pub use tracing;

/// Result type used by generated file services.
pub type FileResult<T> = Result<T, FileError>;

/// Stream of byte chunks used by file upload and download abstractions.
pub type FileByteStream<'a> = Pin<Box<dyn Stream<Item = Result<Bytes, FileError>> + Send + 'a>>;

/// Owned stream for download responses.
pub type OwnedFileByteStream = FileByteStream<'static>;

/// Errors surfaced by generated file services.
///
/// The generated server answers with [`FileError::status`] and a JSON body
/// `{"error": <client_message>}`. Variants whose message the client sees say
/// so; never put internal detail in those.
#[derive(Debug, Clone, Error)]
pub enum FileError {
    /// The request is malformed. `400`; the message is sent to the client.
    #[error("Bad request: {0}")]
    BadRequest(String),
    /// No valid credential was presented. `401`.
    #[error("Authentication required")]
    Unauthorized,
    /// The caller lacks the required permissions. `403`.
    #[error("Forbidden")]
    Forbidden,
    /// The request or part has a content type the endpoint does not accept.
    /// `415`; the message is sent to the client.
    #[error("Unsupported media type: {0}")]
    UnsupportedMediaType(String),
    /// A part or the whole request is over its byte limit. `413`.
    #[error("Payload too large")]
    PayloadTooLarge,
    /// The requested file does not exist. `404`.
    #[error("File not found")]
    NotFound,
    /// The request conflicts with the current state, such as an upload to a
    /// name that exists. `409`; the message is sent to the client.
    #[error("Conflict: {0}")]
    Conflict(String),
    /// A conditional header such as `If-Match` did not hold. `412`; the
    /// message is sent to the client.
    #[error("Precondition failed: {0}")]
    PreconditionFailed(String),
    /// Storing an upload failed. `400`; the client sees `Upload failed` and
    /// the message stays on the server.
    #[error("Upload failed: {0}")]
    UploadFailed(String),
    /// Producing a download failed. `500`; the client sees
    /// `Internal server error` and the message stays on the server.
    #[error("Download failed: {0}")]
    DownloadFailed(String),
    /// The handler broke a rule the generated server enforces, such as
    /// returning from an upload part without reading a file part to the end.
    /// `400`; the message is sent to the client.
    #[error("Handler contract violation: {0}")]
    HandlerContract(String),
    /// An unspecified server-side failure. `500`.
    #[error("Internal server error")]
    Internal,
}

impl FileError {
    /// Returns the HTTP status the generated server answers with for this
    /// error.
    pub fn status(&self) -> StatusCode {
        match self {
            Self::BadRequest(_) | Self::HandlerContract(_) => StatusCode::BAD_REQUEST,
            Self::Unauthorized => StatusCode::UNAUTHORIZED,
            Self::Forbidden => StatusCode::FORBIDDEN,
            Self::UnsupportedMediaType(_) => StatusCode::UNSUPPORTED_MEDIA_TYPE,
            Self::PayloadTooLarge => StatusCode::PAYLOAD_TOO_LARGE,
            Self::NotFound => StatusCode::NOT_FOUND,
            Self::Conflict(_) => StatusCode::CONFLICT,
            Self::PreconditionFailed(_) => StatusCode::PRECONDITION_FAILED,
            Self::UploadFailed(_) => StatusCode::BAD_REQUEST,
            Self::DownloadFailed(_) | Self::Internal => StatusCode::INTERNAL_SERVER_ERROR,
        }
    }

    /// Returns the message the generated server sends to the client.
    ///
    /// For `BadRequest`, `UnsupportedMediaType`, `Conflict`,
    /// `PreconditionFailed` and `HandlerContract` this is the variant's own
    /// message. Every other variant maps to a fixed text, so the detail in
    /// `UploadFailed` and `DownloadFailed` never reaches the client.
    pub fn client_message(&self) -> String {
        match self {
            Self::BadRequest(message)
            | Self::UnsupportedMediaType(message)
            | Self::Conflict(message)
            | Self::PreconditionFailed(message)
            | Self::HandlerContract(message) => message.clone(),
            Self::Unauthorized => "Authentication required".to_string(),
            Self::Forbidden => "Forbidden".to_string(),
            Self::PayloadTooLarge => "Payload too large".to_string(),
            Self::NotFound => "File not found".to_string(),
            Self::UploadFailed(_) => "Upload failed".to_string(),
            Self::DownloadFailed(_) | Self::Internal => "Internal server error".to_string(),
        }
    }

    /// Creates a [`FileError::BadRequest`]. The client sees `message`.
    pub fn bad_request(message: impl Into<String>) -> Self {
        Self::BadRequest(message.into())
    }

    /// Creates a [`FileError::UnsupportedMediaType`]. The client sees
    /// `message`.
    pub fn unsupported_media_type(message: impl Into<String>) -> Self {
        Self::UnsupportedMediaType(message.into())
    }

    /// Creates a [`FileError::UploadFailed`]. The client sees only
    /// `Upload failed`; `message` is for logs.
    pub fn upload_failed(message: impl Into<String>) -> Self {
        Self::UploadFailed(message.into())
    }

    /// Creates a [`FileError::DownloadFailed`]. The client sees only
    /// `Internal server error`; `message` is for logs.
    pub fn download_failed(message: impl Into<String>) -> Self {
        Self::DownloadFailed(message.into())
    }

    /// Creates a [`FileError::HandlerContract`]. The client sees `message`.
    pub fn handler_contract(message: impl Into<String>) -> Self {
        Self::HandlerContract(message.into())
    }
}

/// Request metadata passed to file-service handlers.
///
/// The generated server builds it after authentication and the permission
/// check, so a handler only runs for a caller the endpoint admits.
pub struct FileRequestContext<'a> {
    /// The HTTP method: `POST` for uploads, `GET` for downloads.
    pub method: &'static str,
    /// The request path below the service's `base_path`, such as
    /// `/download/abc123`. The router's `nest` strips the base path.
    pub request_path: &'a str,
    /// The endpoint's route template below `base_path`, such as
    /// `/download/{file_id}`.
    pub matched_path: &'static str,
    /// The request headers, credentials included; do not log them as they
    /// are.
    pub headers: &'a HeaderMap,
    /// The authenticated caller. `Some` on a `WITH_PERMISSIONS` endpoint.
    /// On an `OPTIONAL_AUTH` endpoint it is `Some` only when the request
    /// carried a valid credential, and on an `UNAUTHORIZED` endpoint it is
    /// always `None`.
    pub user: Option<&'a AuthenticatedUser>,
}

impl<'a> FileRequestContext<'a> {
    /// Creates a context from its parts. The generated server calls this;
    /// handlers receive a finished context.
    pub fn new(
        method: &'static str,
        request_path: &'a str,
        matched_path: &'static str,
        headers: &'a HeaderMap,
        user: Option<&'a AuthenticatedUser>,
    ) -> Self {
        Self {
            method,
            request_path,
            matched_path,
            headers,
            user,
        }
    }

    /// Returns the `Range` header, unparsed.
    ///
    /// `None` when the header is missing or is not visible ASCII. The
    /// generated server never serves partial content itself; a handler that
    /// supports ranges parses this and answers `206`.
    pub fn range(&self) -> Option<&'a str> {
        self.headers.get(header::RANGE)?.to_str().ok()
    }

    /// Returns the `If-None-Match` header, unparsed. `None` when the header
    /// is missing or is not visible ASCII.
    pub fn if_none_match(&self) -> Option<&'a str> {
        self.headers.get(header::IF_NONE_MATCH)?.to_str().ok()
    }

    /// Returns the `If-Match` header, unparsed. `None` when the header is
    /// missing or is not visible ASCII.
    pub fn if_match(&self) -> Option<&'a str> {
        self.headers.get(header::IF_MATCH)?.to_str().ok()
    }
}

/// Streaming upload file part passed to service implementations.
///
/// The handler must read the part to the end, with
/// [`next_chunk`](Self::next_chunk) until it returns `None` or with
/// [`drain`](Self::drain), before its part method returns. Otherwise the
/// generated server aborts the upload with [`FileError::HandlerContract`].
///
/// An error from [`next_chunk`](Self::next_chunk) ends the part: every later
/// read returns the same error, and the generated server aborts the upload
/// with it even if the part method swallows it and returns `Ok`.
pub struct IncomingFile<'a> {
    field_name: String,
    file_name: Option<String>,
    content_type: Option<String>,
    headers: HeaderMap,
    limit: u64,
    bytes_read: u64,
    finished: bool,
    error: Option<FileError>,
    stream: FileByteStream<'a>,
}

impl<'a> IncomingFile<'a> {
    /// Wraps a part's byte stream. The generated server calls this.
    ///
    /// `file_name` should already be sanitized; the generated server passes
    /// it through [`sanitize_filename`]. `limit` is the most bytes
    /// [`next_chunk`](Self::next_chunk) returns before it fails.
    pub fn new(
        field_name: impl Into<String>,
        file_name: Option<String>,
        content_type: Option<String>,
        headers: HeaderMap,
        limit: u64,
        stream: FileByteStream<'a>,
    ) -> Self {
        Self {
            field_name: field_name.into(),
            file_name,
            content_type,
            headers,
            limit,
            bytes_read: 0,
            finished: false,
            error: None,
            stream,
        }
    }

    /// Returns the multipart field name.
    pub fn field_name(&self) -> &str {
        &self.field_name
    }

    /// Returns the client's filename for the part, reduced by the generated
    /// server to one path component with [`sanitize_filename`].
    ///
    /// `None` when the client sent no filename. It is still client input:
    /// join it to a directory you chose, and expect duplicates.
    pub fn file_name(&self) -> Option<&str> {
        self.file_name.as_deref()
    }

    /// Returns the part's `Content-Type` as the client declared it. `None`
    /// when the part has none. The bytes are not checked against it.
    pub fn content_type(&self) -> Option<&str> {
        self.content_type.as_deref()
    }

    /// Returns the part's own headers, not the request headers.
    pub fn headers(&self) -> &HeaderMap {
        &self.headers
    }

    /// Returns how many bytes [`next_chunk`](Self::next_chunk) has returned
    /// so far.
    pub fn bytes_read(&self) -> u64 {
        self.bytes_read
    }

    /// Returns the byte limit for this part: the part's `max_bytes`, or less
    /// when the request's `max_total_bytes` leaves less room.
    pub fn limit(&self) -> u64 {
        self.limit
    }

    /// Returns `true` once [`next_chunk`](Self::next_chunk) has reached the
    /// end of the part. A part that failed is never finished.
    pub fn is_finished(&self) -> bool {
        self.finished
    }

    /// Returns the error that ended the part, if
    /// [`next_chunk`](Self::next_chunk) failed.
    pub fn error(&self) -> Option<&FileError> {
        self.error.as_ref()
    }

    /// Returns the next chunk of the part, or `None` at the end.
    ///
    /// After the end every call returns `None`. Chunk sizes follow the
    /// transport, not a fixed size.
    ///
    /// # Errors
    ///
    /// Returns [`FileError::PayloadTooLarge`] when the chunk would take the
    /// part over [`limit`](Self::limit); that chunk is discarded and
    /// [`bytes_read`](Self::bytes_read) does not count it. Errors from the
    /// underlying stream pass through, which in the generated server are
    /// `BadRequest` for a malformed multipart body and `PayloadTooLarge` for a
    /// body over the server's size limit. Return the error from the part
    /// method; the upload cannot continue. The error is final: later calls
    /// return it again.
    pub async fn next_chunk(&mut self) -> FileResult<Option<Bytes>> {
        if let Some(error) = &self.error {
            return Err(error.clone());
        }
        if self.finished {
            return Ok(None);
        }

        let chunk = match self.stream.next().await {
            Some(Ok(chunk)) => chunk,
            Some(Err(error)) => return Err(self.fail(error)),
            None => {
                self.finished = true;
                return Ok(None);
            }
        };

        match self.bytes_read.checked_add(chunk.len() as u64) {
            Some(next_total) if next_total <= self.limit => {
                self.bytes_read = next_total;
                Ok(Some(chunk))
            }
            _ => Err(self.fail(FileError::PayloadTooLarge)),
        }
    }

    /// Records `error` as the part's final error and returns it.
    fn fail(&mut self, error: FileError) -> FileError {
        self.error = Some(error.clone());
        error
    }

    /// Reads the rest of the part and discards it.
    ///
    /// The discarded bytes still count toward the part's limit.
    ///
    /// # Errors
    ///
    /// Returns the same errors as [`next_chunk`](Self::next_chunk).
    pub async fn drain(&mut self) -> FileResult<()> {
        while self.next_chunk().await?.is_some() {}
        Ok(())
    }
}

/// Summary of accepted upload fields, passed to the upload's finish method.
#[derive(Debug, Clone, Default)]
pub struct UploadSummary {
    /// How many parts were accepted.
    pub total_parts: usize,
    /// The bytes of all accepted parts together.
    pub total_bytes: u64,
    /// One entry per accepted part, in the order they arrived.
    pub fields: Vec<UploadFieldSummary>,
}

impl UploadSummary {
    /// Adds one accepted part of `bytes` bytes. The generated server calls
    /// this after each part method succeeds.
    pub fn record(&mut self, field_name: impl Into<String>, bytes: u64) {
        self.total_parts += 1;
        self.total_bytes += bytes;
        self.fields.push(UploadFieldSummary {
            field_name: field_name.into(),
            bytes,
        });
    }
}

/// One accepted part in an [`UploadSummary`].
#[derive(Debug, Clone)]
pub struct UploadFieldSummary {
    /// The multipart field name.
    pub field_name: String,
    /// The part's size in bytes.
    pub bytes: u64,
}

/// JSON response returned by upload lifecycle finish handlers.
///
/// The generated server serializes `body` as JSON and sends it with `status`
/// and `headers`.
#[derive(Debug, Clone)]
pub struct JsonResponse<T> {
    /// The response status.
    pub status: StatusCode,
    /// Extra response headers.
    pub headers: HeaderMap,
    /// The value serialized as the response body.
    pub body: T,
}

impl<T> JsonResponse<T> {
    /// Creates a `200 OK` response with no extra headers.
    pub fn ok(body: T) -> Self {
        Self {
            status: StatusCode::OK,
            headers: HeaderMap::new(),
            body,
        }
    }

    /// Creates a `201 Created` response with no extra headers.
    pub fn created(body: T) -> Self {
        Self {
            status: StatusCode::CREATED,
            headers: HeaderMap::new(),
            body,
        }
    }

    /// Creates a response with `status` and no extra headers.
    pub fn with_status(status: StatusCode, body: T) -> Self {
        Self {
            status,
            headers: HeaderMap::new(),
            body,
        }
    }

    /// Returns the response with header `name` set to `value`, replacing any
    /// earlier value for that name.
    pub fn header(mut self, name: header::HeaderName, value: HeaderValue) -> Self {
        self.headers.insert(name, value);
        self
    }

    /// Splits the response into status, headers and body.
    pub fn into_parts(self) -> (StatusCode, HeaderMap, T) {
        (self.status, self.headers, self.body)
    }
}

impl<T> From<T> for JsonResponse<T> {
    fn from(body: T) -> Self {
        Self::ok(body)
    }
}

/// Download body data.
pub enum DownloadBody {
    /// No body, as for `304 Not Modified`.
    Empty,
    /// A body already in memory.
    Bytes(Bytes),
    /// A body produced chunk by chunk.
    Stream(OwnedFileByteStream),
}

/// Streaming download response returned by download handlers.
///
/// The constructors set the status and body; the builder methods add
/// headers. Each header method replaces an earlier value for the same name.
pub struct DownloadResponse {
    /// The response status.
    pub status: StatusCode,
    /// The response headers.
    pub headers: HeaderMap,
    /// The response body.
    pub body: DownloadBody,
}

impl DownloadResponse {
    /// Creates a response with `status`, no headers and no body.
    pub fn empty(status: StatusCode) -> Self {
        Self {
            status,
            headers: HeaderMap::new(),
            body: DownloadBody::Empty,
        }
    }

    /// Creates a `200 OK` response whose body is `bytes`.
    pub fn bytes(bytes: impl Into<Bytes>) -> Self {
        Self {
            status: StatusCode::OK,
            headers: HeaderMap::new(),
            body: DownloadBody::Bytes(bytes.into()),
        }
    }

    /// Creates a `200 OK` response whose body is read from `stream`.
    ///
    /// The status and headers go out before the first chunk. An `Err` from
    /// the stream ends the transfer early, so the client sees a broken body,
    /// not an error status. Set `Content-Length` when the size is known, so
    /// the client can tell a short body from a complete one.
    pub fn stream(stream: OwnedFileByteStream) -> Self {
        Self {
            status: StatusCode::OK,
            headers: HeaderMap::new(),
            body: DownloadBody::Stream(stream),
        }
    }

    /// Returns the response with its status replaced by `status`, such as
    /// `206 Partial Content`.
    pub fn status(mut self, status: StatusCode) -> Self {
        self.status = status;
        self
    }

    /// Returns the response with header `name` set to `value`.
    pub fn header(mut self, name: header::HeaderName, value: HeaderValue) -> Self {
        self.headers.insert(name, value);
        self
    }

    /// Sets `Content-Type`.
    ///
    /// # Errors
    ///
    /// Returns [`FileError::BadRequest`] when `value` is not a valid header
    /// value, such as one with a control character.
    pub fn content_type(self, value: impl AsRef<str>) -> FileResult<Self> {
        let value = HeaderValue::from_str(value.as_ref())
            .map_err(|e| FileError::bad_request(format!("invalid content type: {e}")))?;
        Ok(self.header(header::CONTENT_TYPE, value))
    }

    /// Sets `Content-Length` to `value` bytes.
    ///
    /// The value must match the body; the server does not check it.
    pub fn content_length(self, value: u64) -> Self {
        self.header(header::CONTENT_LENGTH, HeaderValue::from(value))
    }

    /// Sets `Content-Disposition: attachment` for `filename`.
    ///
    /// Control characters are stripped, then the name is emitted twice per
    /// RFC 6266: as a quoted-string `filename="..."` with `"` and `\`
    /// backslash-escaped and non-ASCII replaced by `_` for legacy agents, and
    /// as an RFC 5987 `filename*=UTF-8''...` percent-encoded parameter that
    /// preserves the original Unicode name for modern agents. Neither form can
    /// break out of the header value.
    ///
    /// Path separators are *not* stripped here (browsers only use the final
    /// component when saving); use [`sanitize_filename`] first if the name
    /// came from an untrusted upload and you want a single path component.
    ///
    /// # Errors
    ///
    /// Returns [`FileError::BadRequest`] if the header value cannot be built,
    /// which the escaping above rules out.
    pub fn attachment(self, filename: impl AsRef<str>) -> FileResult<Self> {
        let name: String = filename
            .as_ref()
            .chars()
            .filter(|c| !c.is_control())
            .collect();
        let quoted = quote_disposition_filename(&name);
        let encoded = rfc5987_encode(&name);
        let value = HeaderValue::from_str(&format!(
            "attachment; filename=\"{quoted}\"; filename*=UTF-8''{encoded}"
        ))
        .map_err(|e| FileError::bad_request(format!("invalid filename: {e}")))?;
        Ok(self.header(header::CONTENT_DISPOSITION, value))
    }

    /// Sets `ETag` to `value` as given, so a strong tag includes its quotes:
    /// `"\"v1\""`.
    ///
    /// # Errors
    ///
    /// Returns [`FileError::BadRequest`] when `value` is not a valid header
    /// value.
    pub fn etag(self, value: impl AsRef<str>) -> FileResult<Self> {
        let value = HeaderValue::from_str(value.as_ref())
            .map_err(|e| FileError::bad_request(format!("invalid etag: {e}")))?;
        Ok(self.header(header::ETAG, value))
    }

    /// Sets `Last-Modified` to `value`, which should be an HTTP date. See
    /// [`last_modified_system_time`](Self::last_modified_system_time) to
    /// format one.
    pub fn last_modified(self, value: HeaderValue) -> Self {
        self.header(header::LAST_MODIFIED, value)
    }

    /// Sets `Last-Modified` from a [`SystemTime`], formatted as an HTTP date.
    pub fn last_modified_system_time(self, value: SystemTime) -> Self {
        let date = httpdate::fmt_http_date(value);
        let value = HeaderValue::from_str(&date).expect("an HTTP date is a valid header value");
        self.header(header::LAST_MODIFIED, value)
    }
}

/// Maximum length in bytes of a sanitized filename.
pub const MAX_FILENAME_BYTES: usize = 255;

/// Reduces an untrusted filename (e.g. a multipart `filename=` parameter) to a
/// single safe path component.
///
/// * Keeps only the final path component, splitting on both `/` and `\`.
/// * Strips NUL and all other control characters (including DEL).
/// * Rejects names that consist only of dots (`.`, `..`, `...`).
/// * Falls back to `"upload"` when nothing usable remains.
/// * Truncates to [`MAX_FILENAME_BYTES`] on a UTF-8 char boundary.
///
/// Unicode is preserved; this is not a transliteration step. Handlers that
/// use the name on a filesystem should still combine it with a trusted
/// directory and never trust it as a full path.
pub fn sanitize_filename(raw: &str) -> String {
    let last_component = raw.rsplit(['/', '\\']).next().unwrap_or("");

    let mut name: String = last_component.chars().filter(|c| !c.is_control()).collect();

    let trimmed = name.trim();
    if trimmed.is_empty() || trimmed.chars().all(|c| c == '.') {
        return "upload".to_string();
    }
    if trimmed.len() != name.len() {
        name = trimmed.to_string();
    }

    if name.len() > MAX_FILENAME_BYTES {
        let mut cut = MAX_FILENAME_BYTES;
        while !name.is_char_boundary(cut) {
            cut -= 1;
        }
        name.truncate(cut);
        // Truncation can leave a dots-only or empty remainder (e.g. many
        // leading dots); re-check so the result is still a usable name.
        if name.is_empty() || name.chars().all(|c| c == '.') {
            return "upload".to_string();
        }
    }

    name
}

/// Build the legacy `filename="..."` quoted-string form: `"` and `\` are
/// backslash-escaped and any non-ASCII or control byte is replaced by `_` so
/// the value is a valid `HeaderValue` and cannot break out of the quotes.
fn quote_disposition_filename(name: &str) -> String {
    let mut out = String::with_capacity(name.len());
    for c in name.chars() {
        match c {
            '"' | '\\' => {
                out.push('\\');
                out.push(c);
            }
            c if c.is_ascii() && !c.is_ascii_control() => out.push(c),
            _ => out.push('_'),
        }
    }
    out
}

/// Percent-encode `name` per RFC 5987 (`attr-char` is left as-is, everything
/// else — including `"`, `\`, `;`, space and all non-ASCII bytes — is encoded).
fn rfc5987_encode(name: &str) -> String {
    const HEX: &[u8; 16] = b"0123456789ABCDEF";
    let mut out = String::with_capacity(name.len() * 3);
    for byte in name.bytes() {
        let is_attr_char = byte.is_ascii_alphanumeric()
            || matches!(
                byte,
                b'!' | b'#' | b'$' | b'&' | b'+' | b'-' | b'.' | b'^' | b'_' | b'`' | b'|' | b'~'
            );
        if is_attr_char {
            out.push(byte as char);
        } else {
            out.push('%');
            out.push(HEX[(byte >> 4) as usize] as char);
            out.push(HEX[(byte & 0x0f) as usize] as char);
        }
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    fn disposition(name: &str) -> String {
        DownloadResponse::empty(StatusCode::OK)
            .attachment(name)
            .expect("attachment header")
            .headers
            .get(header::CONTENT_DISPOSITION)
            .expect("content-disposition set")
            .to_str()
            .unwrap()
            .to_string()
    }

    #[test]
    fn last_modified_system_time_sets_an_http_date() {
        let time = SystemTime::UNIX_EPOCH + std::time::Duration::from_secs(784_111_777);
        let response = DownloadResponse::empty(StatusCode::OK).last_modified_system_time(time);
        assert_eq!(
            response.headers.get(header::LAST_MODIFIED).unwrap(),
            "Sun, 06 Nov 1994 08:49:37 GMT"
        );
    }

    #[test]
    fn f1_sanitize_filename_takes_final_component_of_traversal_names() {
        assert_eq!(sanitize_filename("../../etc/passwd"), "passwd");
        assert_eq!(sanitize_filename("/etc/passwd"), "passwd");
        assert_eq!(
            sanitize_filename("..\\..\\windows\\system.ini"),
            "system.ini"
        );
        assert_eq!(
            sanitize_filename("C:\\Users\\victim\\report.pdf"),
            "report.pdf"
        );
        assert_eq!(sanitize_filename("mixed/sep\\name.txt"), "name.txt");
        // Trailing separator leaves nothing usable.
        assert_eq!(sanitize_filename("dir/"), "upload");
        assert_eq!(sanitize_filename("dir\\"), "upload");
    }

    #[test]
    fn f1_sanitize_filename_rejects_dot_only_and_empty_names() {
        assert_eq!(sanitize_filename(""), "upload");
        assert_eq!(sanitize_filename("   "), "upload");
        assert_eq!(sanitize_filename("."), "upload");
        assert_eq!(sanitize_filename(".."), "upload");
        assert_eq!(sanitize_filename("..."), "upload");
        assert_eq!(sanitize_filename("a/.."), "upload");
        // A dotfile with a real name is fine.
        assert_eq!(sanitize_filename(".env"), ".env");
    }

    #[test]
    fn f1_sanitize_filename_strips_control_characters() {
        assert_eq!(sanitize_filename("evil\0.txt"), "evil.txt");
        assert_eq!(sanitize_filename("a\r\nb.txt"), "ab.txt");
        assert_eq!(sanitize_filename("\x7fdel.txt"), "del.txt");
        assert_eq!(sanitize_filename("\0\0"), "upload");
        // Leading/trailing whitespace is trimmed; interior kept.
        assert_eq!(sanitize_filename("  my file.txt  "), "my file.txt");
    }

    #[test]
    fn f1_sanitize_filename_preserves_unicode_and_caps_on_char_boundary() {
        assert_eq!(sanitize_filename("résumé.pdf"), "résumé.pdf");
        assert_eq!(sanitize_filename("日本語/ファイル.txt"), "ファイル.txt");

        // 'é' is 2 bytes; 130 of them = 260 bytes, cap is 255 bytes (odd) so
        // the cut must land on a boundary at 254.
        let long = "é".repeat(130);
        let out = sanitize_filename(&long);
        assert_eq!(out.len(), 254);
        assert!(out.chars().all(|c| c == 'é'));

        let ascii = "a".repeat(300);
        assert_eq!(sanitize_filename(&ascii).len(), MAX_FILENAME_BYTES);
        assert_eq!(sanitize_filename(&"a".repeat(255)).len(), 255);
    }

    #[test]
    fn f1_attachment_escapes_quotes_and_backslashes() {
        let value = disposition(r#"a"b\c.txt"#);
        assert_eq!(
            value,
            r#"attachment; filename="a\"b\\c.txt"; filename*=UTF-8''a%22b%5Cc.txt"#
        );
        // Injection attempt: cannot terminate the quoted string / add params.
        let value = disposition("x\"; filename=\"evil.exe");
        assert!(value.starts_with("attachment; filename=\"x\\\"; filename=\\\"evil.exe\";"));
        assert!(value.ends_with("filename*=UTF-8''x%22%3B%20filename%3D%22evil.exe"));
    }

    #[test]
    fn f1_attachment_of_sanitized_traversal_name_is_single_component() {
        assert_eq!(
            disposition(&sanitize_filename("../../etc/passwd")),
            "attachment; filename=\"passwd\"; filename*=UTF-8''passwd"
        );
        assert_eq!(
            disposition(&sanitize_filename("..\\..\\boot.ini")),
            "attachment; filename=\"boot.ini\"; filename*=UTF-8''boot.ini"
        );
        // Unsanitized, separators are escaped/encoded but never break the header.
        assert_eq!(
            disposition("..\\..\\boot.ini"),
            "attachment; filename=\"..\\\\..\\\\boot.ini\"; filename*=UTF-8''..%5C..%5Cboot.ini"
        );
    }

    #[test]
    fn f1_attachment_encodes_unicode_with_rfc5987_and_ascii_fallback() {
        assert_eq!(
            disposition("résumé.pdf"),
            "attachment; filename=\"r_sum_.pdf\"; filename*=UTF-8''r%C3%A9sum%C3%A9.pdf"
        );
        // Control chars are stripped before the header is built, so the header
        // value is always valid.
        assert_eq!(
            disposition("a\r\nSet-Cookie: x.txt"),
            "attachment; filename=\"aSet-Cookie: x.txt\"; filename*=UTF-8''aSet-Cookie%3A%20x.txt"
        );
    }
}
